// Package handlers holds the HTTP handlers. Handlers call store repositories;
// they never issue raw SQL and never spawn background work (codex principles 2
// and 3).
package handlers

import (
	"net/http"

	"codexapp/store"
)

// Handlers wires the HTTP surface to the store repositories.
type Handlers struct {
	Users  store.Users
	Orders store.Orders
}

// GetUser returns a single user by id — synchronous, via the store.
func (h *Handlers) GetUser(w http.ResponseWriter, r *http.Request) {
	// decode id from r, call h.Users.ByID, encode to w. Synchronous; returns.
	_ = w
	_ = r
}

// Package store holds the repository interfaces. Per the codex, ALL persistence
// goes through here — handlers never issue raw SQL.
package store

// User is a persisted user.
type User struct {
	ID   int64
	Name string
}

// Order is a persisted order.
type Order struct {
	ID     int64
	UserID int64
	Total  int64
}

// Users is the user repository.
type Users interface {
	ByID(id int64) (User, error)
}

// Orders is the order repository.
type Orders interface {
	RecentByUser(userID int64, limit int) ([]Order, error)
}

// Package cache is the in-process cache. Per the codex there is NO external
// cache service — this lives in the process address space.
package cache

import "sync"

// Cache is a simple in-process key/value cache with no external dependency.
type Cache struct {
	mu sync.RWMutex
	m  map[string]any
}

// New builds an empty in-process cache.
func New() *Cache { return &Cache{m: map[string]any{}} }

// Get returns the cached value for key.
func (c *Cache) Get(key string) (any, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	v, ok := c.m[key]
	return v, ok
}

// Set stores value under key.
func (c *Cache) Set(key string, value any) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.m[key] = value
}

